import { useEffect, useState } from "react"

const App = () => {
  const [count, setCount] = useState(0)
  const [countByTwo, setCountByTwo] = useState(count);

  const handleIncrement = () => {
    setCount(count + 1)
  }

  const handleDecrement = () => {
    setCount(count - 1)
  }

  useEffect(() => {
    console.log("count", count)
  }, [count, setCount])

  return (
    <div className="flex flex-col items-center justify-center bg-gray-800 min-h-screen text-white">
      <h1 className="text-4xl font-bold">Hello World</h1>
      <p className="text-2xl font-bold">Count: {count}</p>
      <div className="flex gap-4 mt-4">
        <button className="bg-blue-500 text-white p-2 rounded-md" onClick={handleIncrement}>Increment</button>
        <button className="bg-red-500 text-white p-2 rounded-md" onClick={handleDecrement}>Decrement</button>
      </div>

      <div className="flex gap-4 mt-4">
        <button className="bg-blue-500 text-white p-2 rounded-md" onClick={() => setCountByTwo(countByTwo + 2)}>Increment by Two</button>
        <button className="bg-red-500 text-white p-2 rounded-md" onClick={() => setCountByTwo(countByTwo - 2)}>Decrement by Two</button>
      </div>
    </div>
  )
}

export default App

:root {
  font-family: system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #242424;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  font-weight: 500;
  color: #646cff;
  text-decoration: inherit;
}
a:hover {
  color: #535bf2;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  min-width: 320px;
  min-height: 100vh;
}

h1 {
  font-size: 3.2em;
  line-height: 1.1;
}

button {
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 1em;
  font-weight: 500;
  font-family: inherit;
  background-color: #1a1a1a;
  cursor: pointer;
  transition: border-color 0.25s;
}
button:hover {
  border-color: #646cff;
}
button:focus,
button:focus-visible {
  outline: 4px auto -webkit-focus-ring-color;
}

@media (prefers-color-scheme: light) {
  :root {
    color: #213547;
    background-color: #ffffff;
  }
  a:hover {
    color: #747bff;
  }
  button {
    background-color: #f9f9f9;
  }
}

